{
  "timeline": [
    {
      "date": "2024-11-05",
      "headline": "2024 United States Presidential Election",
      "text": "Presidential elections were held in the United States. The Republican Party's ticket—Donald Trump and JD Vance—defeated the Democratic Party's ticket—Kamala Harris and Tim Walz."
    },
    {
      "date": "2025-01-20",
      "headline": "Inauguration of Donald Trump and JD Vance",
      "text": "Donald Trump and JD Vance are scheduled to be inaugurated as the 47th president and the 50th vice president of the United States, following their formal election by the Electoral College."
    }
  ]
}

{
  "timeline": [
    {
      "date": "2020-02-03",
      "headline": "Iowa Caucuses",
      "text": "The Iowa caucuses were the first nominating contest in the Democratic Party primaries for the 2020 presidential election."
    },
    {
      "date": "2020-03-03",
      "headline": "Super Tuesday",
      "text": "Super Tuesday was held, with 14 states and one territory holding primaries. Joe Biden emerged as the frontrunner for the Democratic nomination."
    },
    {
      "date": "2020-08-11",
      "headline": "Kamala Harris Announced as Running Mate",
      "text": "Joe Biden announced Kamala Harris as his vice-presidential running mate, making her the first African American and South Asian American woman on a major party's presidential ticket."
    },
    {
      "date": "2020-08-17",
      "headline": "Democratic National Convention",
      "text": "The Democratic National Convention was held virtually due to the COVID-19 pandemic, where Joe Biden was formally nominated as the Democratic candidate for president."
    },
    {
      "date": "2020-08-24",
      "headline": "Republican National Convention",
      "text": "The Republican National Convention was held, and Donald Trump was formally nominated for a second term as president."
    },
    {
      "date": "2020-09-29",
      "headline": "First Presidential Debate",
      "text": "The first presidential debate between Donald Trump and Joe Biden took place in Cleveland, Ohio."
    },
    {
      "date": "2020-10-22",
      "headline": "Final Presidential Debate",
      "text": "The final presidential debate was held in Nashville, Tennessee, focusing on key issues such as COVID-19, climate change, and national security."
    },
    {
      "date": "2020-11-03",
      "headline": "Election Day",
      "text": "The United States presidential election was held. Joe Biden and Kamala Harris were elected as president and vice president, defeating incumbents Donald Trump and Mike Pence."
    },
    {
      "date": "2020-12-14",
      "headline": "Electoral College Vote",
      "text": "The Electoral College formally cast their votes, confirming Joe Biden's victory with 306 electoral votes to Donald Trump's 232."
    },
    {
      "date": "2021-01-06",
      "headline": "Congress Certifies Election Results",
      "text": "The United States Congress certified the Electoral College results, affirming Joe Biden's win, despite objections from some Republican lawmakers."
    },
    {
      "date": "2021-01-20",
      "headline": "Inauguration of Joe Biden",
      "text": "Joe Biden was inaugurated as the 46th president of the United States, and Kamala Harris as vice president, marking the official start of their administration."
    }
  ]
}

