    },
    {
      "date": "1543",
      "headline": "Arrival of the Portuguese",
      "text": "Portuguese traders arrive in Japan, introducing firearms and initiating the Nanban trade period."
    },
    {
      "date": "1603",
      "headline": "Edo Period Begins",
      "text": "The Edo period begins with the establishment of the Tokugawa shogunate, a time of peace, isolation, and economic growth."
    },
    {
      "date": "1853",
      "headline": "Commodore Perry's Arrival",
      "text": "Commodore Matthew Perry of the United States arrives in Japan, leading to the end of Japan's isolationist policy and the signing of the Treaty of Kanagawa."
    },
    {
      "date": "1868",
      "headline": "Meiji Restoration",
      "text": "The Meiji Restoration marks the end of the Tokugawa shogunate and the restoration of imperial rule under Emperor Meiji, initiating a period of rapid modernization and industrialization."
    },
    {
      "date": "1945",
      "headline": "End of World War II",
      "text": "Japan surrenders to the Allied forces, marking the end of World War II and the beginning of the Allied occupation of Japan."
    },
    {
      "date": "1947",
      "headline": "Postwar Constitution Enacted",
      "text": "Japan enacts a new constitution, establishing a parliamentary system and renouncing war as a means of settling international disputes."
    },
    {
      "date": "1964",
      "headline": "Tokyo Olympics",
      "text": "Tokyo hosts the Summer Olympics, symbolizing Japan's postwar recovery and re-emergence on the global stage."
    },
    {
