    {
      "date": "1909-02-28",
      "headline": "First National Woman's Day",
      "text": "The first National Woman's Day was observed in the United States on February 28, 1909, organized by the Socialist Party of America in honor of the 1908 garment workers' strike in New York."
    },
    {
      "date": "1910",
      "headline": "International Women's Day Proposal",
      "text": "At the International Socialist Woman's Conference in Copenhagen, Clara Zetkin proposed the establishment of an annual International Women's Day to advocate for women's rights and suffrage."
    },
    {
      "date": "1911-03-19",
      "headline": "First International Women's Day",
      "text": "International Women's Day was celebrated for the first time in Austria, Denmark, Germany, and Switzerland on March 19, 1911, with rallies attended by over a million people advocating for women's rights."
    },
    {
      "date": "1913-1914",
      "headline": "IWD and Peace Movement",
      "text": "As part of the peace movement during World War I, Russian women observed their first International Women's Day on the last Sunday in February 1913. In 1914, International Women's Day was held on March 8 in Germany, possibly because that day was a Sunday."
    },
    {
      "date": "1917-03-08",
      "headline": "Russian Women's Strike",
      "text": "On March 8, 1917, women in Petrograd (now St. Petersburg) went on strike for 'Bread and Peace,' which marked the beginning of the Russian Revolution. This event led to the abdication of the Tsar and the granting of women's suffrage in Russia."
    },
    {
      "date": "1975",
      "headline": "UN Recognition",
      "text": "The United Nations began celebrating International Women's Day on March 8 during International Women's Year in 1975."
    },
    {
      "date": "1977",
      "headline": "UN General Assembly Proclamation",
      "text": "In 1977, the United Nations General Assembly invited member states to proclaim March 8 as the UN Day for women's rights and world peace."
    }
  ]
}

