{
  "timeline": [
    {
      "date": "-0800",
      "headline": "Germanic Tribes",
      "text": "The Germanic tribes began to emerge in Northern Europe around 800 BCE. These tribes would later play a significant role in the history of the region that is now Germany."
    },
    {
      "date": "0009",
      "headline": "Battle of the Teutoburg Forest",
      "text": "A coalition of Germanic tribes led by Arminius defeated three Roman legions, halting Roman expansion into Germania."
    },
    {
      "date": "0843",
      "headline": "Treaty of Verdun",
      "text": "The Carolingian Empire was divided into three kingdoms, leading to the formation of East Francia, which would become the Holy Roman Empire and later Germany."
    },
    {
      "date": "1517",
      "headline": "Martin Luther's 95 Theses",
      "text": "Martin Luther published his 95 Theses, sparking the Protestant Reformation and leading to significant religious and political changes in Germany and Europe."
    },
    {
      "date": "1618",
      "headline": "Start of the Thirty Years' War",
      "text": "A series of conflicts primarily fought in Central Europe, including Germany, which devastated the region and significantly altered its political landscape."
    },
    {
      "date": "1648",
      "headline": "Peace of Westphalia",
      "text": "The treaties ended the Thirty Years' War and marked the beginning of the modern state system, with significant territorial and political changes in Germany."
    },
    {
      "date": "1871-01-18",
      "headline": "German Unification",
      "text": "The German Empire was proclaimed in the Hall of Mirrors at the Palace of Versailles, unifying various German states under Prussian leadership."
    },
    {
      "date": "1914-1918",
      "headline": "World War I",
      "text": "Germany was a central power in World War I, which ended with its defeat and significant territorial and political changes."
    },
    {
      "date": "1919-06-28",
      "headline": "Treaty of Versailles",
      "text": "The treaty formally ended World War I, imposing heavy reparations and territorial losses on Germany."
    },
    {
      "date": "1933-01-30",
      "headline": "Adolf Hitler Becomes Chancellor",
      "text": "Adolf Hitler was appointed Chancellor of Germany, leading to the establishment of a totalitarian regime and the onset of World War II."
    },
    {
      "date": "1939-1945",
      "headline": "World War II",
      "text": "Germany, under Nazi rule, initiated World War II, which resulted in widespread devastation and the eventual defeat of Germany."
    },
    {
      "date": "1949-05-23",
      "headline": "Founding of the Federal Republic of Germany",
      "text": "The Federal Republic of Germany (West Germany) was established, marking the division of Germany into East and West during the Cold War."
    },
    {
      "date": "1989-11-09",
      "headline": "Fall of the Berlin Wall",
      "text": "The Berlin Wall, a symbol of the Cold War division between East and West Germany, fell, leading to the reunification of Germany."
    },
    {
      "date": "1990-10-03",
      "headline": "German Reunification",
      "text": "East and West Germany were officially reunified, marking the end of the Cold War division and the establishment of a single German state."
    },
    {
      "date": "2002-01-01",
