{
  "timeline": [
    {
      "date": "1869",
      "headline": "Mendeleev's Periodic Table",
      "text": "Dmitri Mendeleev published the first recognizable periodic table, arranging the 63 known elements into a table based on atomic mass, which showed that elements with similar properties occurred at regular intervals."
    },
    {
      "date": "1869",
      "headline": "Mendeleev's Predictions",
      "text": "Mendeleev left gaps in his periodic table for elements that were not yet discovered and predicted the properties of these elements, such as gallium, scandium, and germanium."
    },
    {
      "date": "1871",
      "headline": "Mendeleev's Revised Table",
      "text": "Mendeleev revised his periodic table, correcting the atomic weights of some elements and predicting the existence and properties of additional elements."
    },
    {
      "date": "1894",
      "headline": "Discovery of Noble Gases",
      "text": "William Ramsay and Lord Rayleigh discovered the noble gases, which were added to the periodic table as a new group."
    },
    {
      "date": "1913",
      "headline": "Moseley's Law",
      "text": "Henry Moseley demonstrated that the atomic number, not atomic mass, is the proper basis for the organization of the periodic table, leading to the modern definition of the periodic law."
    },
    {
      "date": "1940",
      "headline": "Discovery of Plutonium",
      "text": "Glenn T. Seaborg and his team discovered plutonium, leading to the identification of the actinide series and the expansion of the periodic table."
    },
    {
      "date": "1945",
      "headline": "Seaborg's Actinide Concept",
      "text": "Glenn T. Seaborg proposed the actinide concept, which reorganized the periodic table by placing the actinide series below the lanthanide series."
    },
    {
      "date": "2016",
      "headline": "Completion of the 7th Period",
      "text": "The International Union of Pure and Applied Chemistry (IUPAC) confirmed the names of four new elements: nihonium, moscovium, tennessine, and oganesson, completing the 7th period of the periodic table."
    }
  ]
}

