      "headline": "Return to India",
      "text": "Gandhi returned to India after completing his studies in law."
    },
    {
      "date": "1893",
      "headline": "Move to South Africa",
      "text": "Gandhi accepted a contract to work for an Indian firm in Natal, South Africa, where he faced racial discrimination."
    },
    {
      "date": "1894",
      "headline": "Formation of Natal Indian Congress",
      "text": "Gandhi founded the Natal Indian Congress to fight discrimination against Indians in South Africa."
    },
    {
      "date": "1906",
      "headline": "First Satyagraha Campaign",
      "text": "Gandhi organized his first mass civil-disobedience campaign, known as Satyagraha, in South Africa."
    },
    {
      "date": "1915",
      "headline": "Return to India",
      "text": "Gandhi returned to India and joined the Indian National Congress, becoming a prominent leader in the Indian independence movement."
    },
    {
      "date": "1917",
      "headline": "Champaran Agitation",
      "text": "Gandhi led a successful protest against oppressive plantation system in Champaran, Bihar."
    },
    {
      "date": "1919",
      "headline": "Rowlatt Act Protests",
      "text": "Gandhi called for a nationwide protest against the Rowlatt Act, which allowed the British to imprison Indians without trial."
    },
    {
      "date": "1920",
      "headline": "Non-Cooperation Movement",
      "text": "Gandhi launched the Non-Cooperation Movement, urging Indians to boycott British goods and institutions."
    },
    {
      "date": "1930-03-12",
      "headline": "Salt March",
      "text": "Gandhi led the Salt March to Dandi to protest the British salt tax, a pivotal event in the Indian independence movement."
    },
    {
      "date": "1942",
      "headline": "Quit India Movement",
      "text": "Gandhi launched the Quit India Movement, demanding an end to British rule in India."
    },
    {
      "date": "1947-08-15",
      "headline": "Indian Independence",
      "text": "India gained independence from British rule, largely due to Gandhi's efforts and leadership."
    },
    {
      "date": "1948-01-30",
      "headline": "Assassination",
      "text": "Gandhi was assassinated by Nathuram Godse, a Hindu nationalist, in New Delhi."
    }
  ]
}

