    },
    {
      "date": "0006",
      "headline": "Visit to the Temple",
      "text": "At the age of 12, Jesus visits the Temple in Jerusalem with his parents, Mary and Joseph, during Passover. He engages with the teachers there, demonstrating his understanding and wisdom."
    },
    {
      "date": "0027",
      "headline": "Baptism by John the Baptist",
      "text": "Jesus is baptized by John the Baptist in the Jordan River, marking the beginning of his public ministry. This event is considered a significant moment in the Gospels."
    },
    {
      "date": "0027",
      "headline": "Temptation in the Desert",
      "text": "Following his baptism, Jesus spends 40 days and nights fasting in the Judean desert, where he is tempted by Satan but resists."
    },
    {
      "date": "0028",
      "headline": "Sermon on the Mount",
      "text": "Jesus delivers the Sermon on the Mount, which includes key teachings such as the Beatitudes and the Lord's Prayer. This sermon is a foundational text for Christian ethics."
    },
    {
      "date": "0029",
      "headline": "Transfiguration",
      "text": "Jesus is transfigured on a mountain, witnessed by Peter, James, and John. His appearance becomes radiant, and he speaks with Moses and Elijah."
    },
    {
      "date": "0030",
      "headline": "Entry into Jerusalem",
      "text": "Jesus enters Jerusalem riding a donkey, an event celebrated as Palm Sunday. This marks the beginning of the final week of his life, known as Holy Week."
    },
    {
      "date": "0030",
      "headline": "Last Supper",
      "text": "Jesus shares a final meal with his disciples, known as the Last Supper, during which he institutes the Eucharist. This event is commemorated on Maundy Thursday."
    },
    {
      "date": "0030",
      "headline": "Crucifixion",
      "text": "Jesus is crucified under the order of Pontius Pilate, the Roman governor, on charges of claiming to be the King of the Jews. This event is central to Christian belief and is commemorated on Good Friday."
    },
    {
      "date": "0030",
      "headline": "Resurrection",
      "text": "According to Christian belief, Jesus is resurrected from the dead on the third day after his crucifixion. This event is celebrated as Easter Sunday and is a cornerstone of Christian faith."
    },
    {
      "date": "0030",
      "headline": "Ascension",
      "text": "Jesus ascends to heaven 40 days after his resurrection, an event witnessed by his disciples. This is celebrated as the Feast of the Ascension."
    }
  ]
}

