{
  "timeline": [
    {
      "date": "0570",
      "headline": "Birth of Muhammad",
      "text": "Muhammad was born in Mecca, in present-day Saudi Arabia, into the Quraysh tribe. His exact birth date is unknown, but it is traditionally celebrated on the 12th of Rabi' al-awwal in the Islamic calendar."
    },
    {
      "date": "0610",
      "headline": "First Revelation",
      "text": "Muhammad received his first revelation from the angel Gabriel in the Cave of Hira, marking the beginning of his role as a prophet. This event is considered the start of the Quran's revelation."
    },
    {
      "date": "0613",
      "headline": "Public Preaching Begins",
      "text": "Muhammad began publicly preaching the message of Islam in Mecca, calling for the worship of one God and rejecting the polytheistic practices of the Quraysh."
    },
    {
      "date": "0619",
      "headline": "Year of Sorrow",
      "text": "Muhammad's wife Khadijah and his uncle Abu Talib, both of whom were his supporters, died in this year, leaving him vulnerable to his opponents in Mecca."
    },
    {
      "date": "0622",
      "headline": "Hijra to Medina",
      "text": "Muhammad and his followers migrated from Mecca to Medina to escape persecution. This migration, known as the Hijra, marks the beginning of the Islamic calendar."
    },
    {
      "date": "0624",
      "headline": "Battle of Badr",
      "text": "Muhammad led his followers to victory in the Battle of Badr against the Quraysh of Mecca, which was a significant turning point for the early Muslim community."
    },
    {
      "date": "0625",
      "headline": "Battle of Uhud",
      "text": "The Muslims faced a setback in the Battle of Uhud against the Quraysh, but Muhammad's leadership helped maintain the unity and morale of his followers."
    },
    {
      "date": "0626",
      "headline": "Battle of the Trench",
      "text": "Muhammad successfully defended Medina from a siege by the Quraysh and their allies by employing innovative tactics, including the digging of a trench."
    },
    {
      "date": "0628",
      "headline": "Treaty of Hudaybiyyah",
      "text": "Muhammad negotiated a ten-year truce with the Quraysh, known as the Treaty of Hudaybiyyah, which allowed Muslims to make a pilgrimage to Mecca the following year."
    },
    {
      "date": "0630",
      "headline": "Conquest of Mecca",
      "text": "Muhammad and his followers peacefully conquered Mecca, and he cleansed the Kaaba of idols, establishing it as the central place of worship for Muslims."
    },
    {
      "date": "0632-03",
      "headline": "Farewell Pilgrimage",
      "text": "Muhammad performed his final pilgrimage to Mecca, known as the Farewell Pilgrimage, during which he delivered his Farewell Sermon, summarizing his teachings."
    },
    {
      "date": "0632-06-08",
      "headline": "Death of Muhammad",
      "text": "Muhammad died in Medina after a brief illness. His death marked the end of the prophetic era in Islam, and he was succeeded by Abu Bakr as the first caliph."
    }
  ]
}

