      "headline": "Battle of Bạch Đằng",
      "text": "The Trần dynasty successfully repels the third Mongol invasion at the Battle of Bạch Đằng River."
    },
    {
      "date": "1407",
      "headline": "Ming Occupation",
      "text": "The Ming dynasty of China invades and occupies Vietnam, ending the Hồ dynasty."
    },
    {
      "date": "1428",
      "headline": "Lê Lợi's Victory",
      "text": "Lê Lợi leads a successful rebellion against the Ming, establishing the Lê dynasty and restoring Vietnamese independence."
    },
    {
      "date": "1802",
      "headline": "Nguyễn Dynasty Founded",
      "text": "Nguyễn Ánh, with French assistance, defeats the Tây Sơn dynasty and establishes the Nguyễn dynasty, unifying Vietnam."
    },
    {
      "date": "1858",
      "headline": "French Colonization Begins",
      "text": "France begins its colonization of Vietnam, starting with the bombardment of Đà Nẵng."
    },
    {
      "date": "1945-09-02",
