{
  "timeline": [
    {
      "date": "-0100",
      "headline": "Birth of Julius Caesar",
      "text": "Gaius Julius Caesar was born in Rome, traditionally on July 12 or 13, 100 BCE, into the patrician family of the Julii, which claimed descent from the goddess Venus."
    },
    {
      "date": "-0078",
      "headline": "Death of Caesar's Father",
      "text": "Caesar's father, also named Gaius Julius Caesar, died suddenly, leaving Caesar as the head of the family at the age of 16."
    },
    {
      "date": "-0075",
      "headline": "Captured by Pirates",
      "text": "While traveling to Rhodes to study oratory, Caesar was captured by Cilician pirates and held for ransom. After his release, he raised a fleet, captured the pirates, and had them executed."
    },
    {
      "date": "-0073",
      "headline": "Elected Pontifex",
      "text": "Caesar was elected as a pontifex, a member of the college of priests, which marked the beginning of his political career."
    },
    {
      "date": "-0069",
      "headline": "Quaestor in Spain",
      "text": "Caesar was elected quaestor and served in the province of Hispania Ulterior (modern-day Spain)."
    },
    {
      "date": "-0065",
      "headline": "Elected Curule Aedile",
      "text": "Caesar was elected curule aedile, responsible for public buildings and festivals, gaining popularity through lavish games and spectacles."
    },
    {
      "date": "-0063",
      "headline": "Elected Pontifex Maximus",
      "text": "Caesar was elected Pontifex Maximus, the chief priest of the Roman state religion, through political maneuvering."
    },
    {
      "date": "-0062",
      "headline": "Elected Praetor",
      "text": "Caesar was elected praetor, an important judicial office, and served in Rome."
    },
    {
      "date": "-0061",
      "headline": "Governor of Further Spain",
      "text": "Caesar served as governor of the province of Hispania Ulterior, where he achieved military successes and paid off his debts."
    },
    {
      "date": "-0060",
      "headline": "Formation of the First Triumvirate",
      "text": "Caesar formed a political alliance with Pompey and Crassus, known as the First Triumvirate, to dominate Roman politics."
    },
    {
      "date": "-0059",
      "headline": "Elected Consul",
      "text": "Caesar was elected consul, the highest office in the Roman Republic, and passed significant reforms, including land redistribution."
    },
    {
      "date": "-0058",
      "headline": "Proconsul of Gaul",
      "text": "Caesar was appointed proconsul of Cisalpine Gaul, Illyricum, and later Transalpine Gaul, beginning his military campaigns in the region."
    },
    {
      "date": "-0058 to -0050",
      "headline": "Gallic Wars",
      "text": "Caesar led Roman forces in the Gallic Wars, expanding Roman territory to the English Channel and the Rhine, and becoming immensely powerful and popular."
    },
    {
      "date": "-0049",
      "headline": "Crossing the Rubicon",
      "text": "Caesar crossed the Rubicon River with his army, defying the Senate and starting a civil war against Pompey and the optimates."
    },
    {
      "date": "-0048",
      "headline": "Battle of Pharsalus",
      "text": "Caesar defeated Pompey's forces at the Battle of Pharsalus in Greece, solidifying his power and leading to Pompey's flight to Egypt."
    },
    {
      "date": "-0046",
      "headline": "Dictator Perpetuo",
      "text": "Caesar was appointed dictator perpetuo (dictator in perpetuity), centralizing power and initiating various reforms in Rome."
    },
    {
      "date": "-0044-03-15",
      "headline": "Assassination of Julius Caesar",
      "text": "Caesar was assassinated by a group of Roman senators, including Brutus and Cassius, on the Ides of March, due to fears of his growing power and potential monarchy."
    }
  ]
}

