      "date": "1932",
      "headline": "Formation of Unit 731",
      "text": "Unit 731 was initially established as the Epidemic Prevention and Water Purification Department of the Kwantung Army in Harbin, Manchukuo, under the command of General Shiro Ishii."
    },
    {
      "date": "1936",
      "headline": "Expansion and Renaming",
      "text": "The unit was expanded and officially became known as Unit 731. It moved to a new facility in Pingfang, Harbin, which became the main site for its operations."
    },
    {
      "date": "1937",
      "headline": "Start of Human Experimentation",
      "text": "Unit 731 began conducting lethal human experimentation, including vivisections and testing of biological weapons, on prisoners and civilians."
    },
    {
      "date": "1939",
      "headline": "Field Testing of Biological Weapons",
      "text": "Unit 731 conducted field tests of biological weapons, including the release of plague-infected fleas, in various locations in China."
    },
    {
      "date": "1940",
      "headline": "Expansion of Operations",
      "text": "Unit 731 expanded its operations to include the development and testing of chemical weapons, alongside its biological warfare research."
    },
    {
      "date": "1942",
      "headline": "Increased Production of Biological Agents",
      "text": "The unit increased the production of biological agents, including anthrax and plague, for potential use in warfare."
    },
    {
      "date": "1945-08",
      "headline": "Destruction of Evidence",
      "text": "As World War II came to an end, Unit 731 attempted to destroy evidence of its activities by demolishing facilities and killing remaining prisoners."
    },
    {
      "date": "1945-09",
      "headline": "Surrender of Japan",
      "text": "Following Japan's surrender, Unit 731 was disbanded. Many of its members were not prosecuted due to deals made with the United States for their research data."
    },
    {
      "date": "1946",
      "headline": "War Crimes Trials",
      "text": "Some members of Unit 731 were tried in the Khabarovsk War Crime Trials by the Soviet Union, revealing details of the unit's activities."
    }
  ]
}

