{
  "timeline": [
    {
      "date": "1994",
      "headline": "Invention of HTTP Cookie",
      "text": "The HTTP cookie was invented by Lou Montulli, a programmer for Netscape Communications, as a way to enable websites to store information on a user's computer and later retrieve it. This was initially intended to solve the problem of how to implement a virtual shopping cart."
    },
    {
      "date": "1995",
      "headline": "First Use of Cookies",
      "text": "Cookies were first used in the Netscape Navigator browser in 1995. They were designed to allow websites to remember stateful information, such as items in a shopping cart or user preferences."
    },
    {
      "date": "1996",
      "headline": "Public Awareness and Privacy Concerns",
      "text": "The Financial Times published an article in February 1996 that brought public attention to cookies and raised privacy concerns. This led to increased scrutiny and discussions about the implications of cookies for user privacy."
    },
    {
      "date": "1997",
      "headline": "Introduction of the 'Set-Cookie' Header",
      "text": "The 'Set-Cookie' HTTP header was introduced as part of the Netscape specification, which allowed servers to send cookies to clients. This became a standard way for web servers to instruct browsers to store cookies."
    },
    {
      "date": "2000",
      "headline": "RFC 2965 - Cookie Specification",
      "text": "The Internet Engineering Task Force (IETF) published RFC 2965, which provided a formal specification for HTTP State Management Mechanism, including cookies. This aimed to standardize the use of cookies across different web browsers."
    },
    {
      "date": "2011",
      "headline": "EU Cookie Directive",
      "text": "The European Union introduced the EU Cookie Directive, which required websites to obtain informed consent from users before storing cookies on their devices. This was part of broader efforts to protect user privacy online."
    },
    {
      "date": "2018",
      "headline": "GDPR Implementation",
      "text": "The General Data Protection Regulation (GDPR) came into effect in the European Union, further strengthening regulations around the use of cookies and requiring explicit consent from users for data collection and processing."
    }
  ]
}

