      "headline": "Union of Krewo",
      "text": "The Union of Krewo initiates a personal union between Poland and Lithuania, leading to the eventual creation of the Polish-Lithuanian Commonwealth."
    },
    {
      "date": "1410-07-15",
      "headline": "Battle of Grunwald",
      "text": "The Polish-Lithuanian alliance defeats the Teutonic Knights in one of the largest battles of medieval Europe, significantly weakening the Order's power."
    },
    {
      "date": "1569",
      "headline": "Union of Lublin",
      "text": "The Union of Lublin formally establishes the Polish-Lithuanian Commonwealth, a dual state of Poland and Lithuania with a common monarch."
    },
    {
      "date": "1772",
      "headline": "First Partition of Poland",
      "text": "The first partition of Poland by Russia, Prussia, and Austria reduces Poland's territory and sovereignty."
    },
    {
      "date": "1791-05-03",
      "headline": "Constitution of May 3",
      "text": "Poland adopts the May 3rd Constitution, the first modern constitution in Europe and the second in the world after the United States."
    },
    {
      "date": "1795",
      "headline": "Third Partition of Poland",
      "text": "The third partition by Russia, Prussia, and Austria leads to the complete dissolution of the Polish-Lithuanian Commonwealth."
    },
    {
      "date": "1918-11-11",
      "headline": "Independence Restored",
      "text": "Poland regains independence after 123 years of partitions, following the end of World War I."
    },
    {
