    },
    {
      "date": "1603",
      "headline": "Establishment of the Tokugawa Shogunate",
      "text": "Tokugawa Ieyasu is appointed shogun by Emperor Go-Yōzei, establishing the Tokugawa Shogunate, which would rule Japan for over 250 years."
    },
    {
      "date": "1868",
      "headline": "Meiji Restoration",
      "text": "The Tokugawa Shogunate is overthrown during the Meiji Restoration, leading to the restoration of imperial rule and the modernization of Japan."
