{
  "timeline": [
    {
      "date": "1865",
      "headline": "Founding of the First Ku Klux Klan",
      "text": "The Ku Klux Klan was founded in Pulaski, Tennessee, by six Confederate veterans. It was established as a social club but quickly evolved into a violent organization aiming to restore white supremacy in the post-Civil War South."
    },
    {
      "date": "1867",
      "headline": "Klan's First National Meeting",
      "text": "The Klan held its first national meeting in Nashville, Tennessee, where it adopted a prescriptive constitution and established a hierarchical structure."
    },
    {
      "date": "1871",
      "headline": "Ku Klux Klan Act",
      "text": "The U.S. Congress passed the Ku Klux Klan Act, also known as the Civil Rights Act of 1871, which authorized President Ulysses S. Grant to declare martial law and use military force to suppress the Klan's activities."
    },
    {
      "date": "1872",
      "headline": "First Klan's Decline",
      "text": "The first iteration of the Klan began to decline due to federal enforcement and internal disorganization. By the mid-1870s, it had largely disbanded."
    },
    {
      "date": "1915",
      "headline": "Second Ku Klux Klan Founded",
      "text": "The second iteration of the Klan was founded in Atlanta, Georgia, by William J. Simmons. It was inspired by the film 'The Birth of a Nation' and focused on nativism, anti-Catholicism, and anti-Semitism, in addition to white supremacy."
    },
    {
      "date": "1920",
      "headline": "Klan's Peak Membership",
      "text": "The second Klan reached its peak membership in the early 1920s, with estimates ranging from 3 to 6 million members nationwide."
    },
    {
      "date": "1925",
      "headline": "Klan March on Washington",
      "text": "The Klan held a massive march in Washington, D.C., showcasing its national influence and political power."
    },
    {
      "date": "1944",
      "headline": "Second Klan's Dissolution",
      "text": "The second Klan officially disbanded due to internal conflicts, financial difficulties, and public backlash against its violent activities."
    },
    {
      "date": "1950s",
      "headline": "Emergence of the Third Ku Klux Klan",
      "text": "The third iteration of the Klan emerged in response to the Civil Rights Movement, focusing on opposing racial integration and civil rights for African Americans."
    },
    {
      "date": "1965",
      "headline": "Klan Violence During Civil Rights Movement",
      "text": "The Klan was involved in numerous acts of violence and intimidation against civil rights activists, including the infamous 1964 murders of three civil rights workers in Mississippi."
    },
    {
      "date": "1980s",
      "headline": "Klan's Decline and Fragmentation",
      "text": "The Klan's influence waned significantly due to legal actions, internal divisions, and the rise of other white supremacist groups. It became fragmented into smaller, independent factions."
    },
    {
      "date": "2000s",
      "headline": "Modern Klan Activity",
      "text": "The Klan remains active in various parts of the United States, though its membership is significantly reduced. It continues to promote white supremacist ideologies and engage in hate crimes."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1916",
      "headline": "First Copa América",
      "text": "The inaugural Copa América was held in 1916 in Argentina to commemorate the centenary of Argentina's independence. It was the first international football tournament in South America."
    },
    {
      "date": "1916-07-09",
      "headline": "First Copa América Final",
      "text": "The final match of the first Copa América was played between Argentina and Uruguay, ending in a 0-0 draw. Uruguay was declared the winner based on points."
    },
    {
      "date": "1917",
      "headline": "Second Copa América",
      "text": "The second edition of the Copa América was held in Uruguay. Uruguay won the tournament, becoming the first team to win the Copa América twice."
    },
    {
      "date": "1921",
      "headline": "Argentina Wins First Title",
      "text": "Argentina won their first Copa América title in 1921 when the tournament was held in Buenos Aires."
    },
    {
      "date": "1925",
      "headline": "Tournament Format Change",
      "text": "The format of the Copa América was changed in 1925, with the tournament being held every two years instead of annually."
    },
    {
      "date": "1939",
      "headline": "Peru Wins First Title",
      "text": "Peru won their first Copa América title in 1939 when the tournament was held in Lima."
    },
    {
      "date": "1975",
      "headline": "Copa América Name Adopted",
      "text": "In 1975, the tournament officially adopted the name 'Copa América'. The format was also changed to include all CONMEBOL teams, and the tournament was held every four years."
    },
    {
      "date": "1987",
      "headline": "Return to Regular Schedule",
      "text": "The Copa América returned to a regular schedule in 1987, being held every two years until 2001."
    },
    {
      "date": "1993",
      "headline": "Introduction of Guest Teams",
      "text": "In 1993, the Copa América began inviting teams from outside South America to participate, starting with Mexico and the United States."
    },
    {
      "date": "2007",
      "headline": "Brazil Wins Eighth Title",
      "text": "Brazil won their eighth Copa América title in 2007, defeating Argentina in the final."
    },
    {
      "date": "2016",
      "headline": "Copa América Centenario",
      "text": "The Copa América Centenario was held in 2016 to commemorate the 100th anniversary of the tournament. It was hosted by the United States and included teams from CONCACAF."
    },
    {
      "date": "2019",
      "headline": "Brazil Wins Ninth Title",
      "text": "Brazil won their ninth Copa América title in 2019, hosting the tournament and defeating Peru in the final."
    },
    {
